-- Executed November15. Petco verified_at was briefly set then restored to original NULL in a separately audited follow-up; script below preserves it directly.
begin;
do $hold$ declare b record; old jsonb; changed jsonb; begin
for b in select * from public.businesses where id in ('77f37ae1-8835-4d96-b716-fc17e4bd9636','d079cd2c-3c92-4216-b59a-8f7cd0959633','0b71e027-f385-4835-b241-64c56eb50046') for update loop
if b.claimed or b.source <> 'manual' or b.source_url is not null or b.verification_source is not null or exists(select 1 from listing_checks where business_id=b.id) then raise exception 'Hold precondition changed'; end if;
old:=to_jsonb(b);
update businesses set verified=false where id=b.id;
select to_jsonb(x) into changed from businesses x where id=b.id;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(b.id,old,changed,'Publication hold pending re-verification: unclaimed legacy manual record has no source/check supporting current identity/contact/location. No closure finding.','docs/research/pet-care-quality-2026-11-15.md');
end loop; end $hold$;
do $petco$ declare bid uuid:='9c032ca1-7799-4206-9836-6de9bc95a046'; old jsonb; changed jsonb; begin
select to_jsonb(b) into old from businesses b where id=bid and name='Petco Manteca' and claimed=false for update;
if old is null or exists(select 1 from listing_checks where business_id=bid) then raise exception 'Petco precondition changed'; end if;
update businesses set address='2184 Daniels St, Manteca, CA 95337-6704',phone='(209) 647-7290',website='https://stores.petco.com/ca/manteca/dog-training-manteca-ca-1351.html',description='Manteca Petco advertises in-store group and private dog training, including puppy and adult programs. Contact the Daniels Street store to confirm eligibility, vaccination requirements, current sessions, total cost and available dates. This check establishes the Manteca facility, not travel coverage or holiday availability.',rating=null,review_count=0,source_url='https://stores.petco.com/ca/manteca/dog-training-manteca-ca-1351.html',verification_source='first_party_website_desk_check' where id=bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://stores.petco.com/ca/manteca/dog-training-manteca-ca-1351.html',array['identity','address','phone','website','advertised services'],array['Manteca'],array['dog training','puppy training'],'Official local service page checked November15,2026: Daniels Street address,2096477290, in-store group/private puppy/adult training. Corrects unsupported legacy Yosemite address/2393004 number; legacy ratings removed without importing testimonials. Manteca facility only; no travel area, credentials, workmanship, availability, holiday hours or methods/safety independently verified. No photos/reviews reused or booking submitted.');
select to_jsonb(b) into changed from businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,old,changed,'Official local service page corrects legacy contact/location and establishes dog-training discovery','https://stores.petco.com/ca/manteca/dog-training-manteca-ca-1351.html');
end $petco$;
do $center$ declare bid uuid; changed jsonb; begin
if exists(select 1 from businesses where name ilike '%Lathrop Animal Center%' or regexp_replace(coalesce(phone,''),'[^0-9]','','g') like '%6476480') then raise exception 'Center duplicate'; end if;
insert into businesses(name,category,city,phone,website,description,status,verified,claimed,rating,review_count,source,source_url,verification_source,verified_at) values('Lathrop Animal Center','Pet Services','Lathrop','(209) 647-6480','https://www.ci.lathrop.ca.us/animal-services','City animal resource for inquiries about listed found and adoptable animals. The official page links to 24Petconnect (use Lathrop 95330) and Adopt-a-Pet. Animal Center inquiries:2096476480. Non-emergency loose/lost dog and field-service calls:2096476400. Confirm procedures directly; no visitor street location, appointment availability or custody outcome established.','approved',true,false,null,0,'editorial_first_party','https://www.ci.lathrop.ca.us/animal-services','first_party_website_desk_check',now()) returning id into bid;
insert into listing_checks(business_id,source_url,checked_fields,service_areas,service_tags,scope_note) values(bid,'https://www.ci.lathrop.ca.us/animal-services',array['identity','public contact routes','website','advertised municipal services'],array['Lathrop'],array['animal services','lost pet resources'],'Official City page freshly read in normal browser November15,2026. Animal Center2096476480 distinguished from non-emergency field dispatch2096476400. Found/adoptable animal links checked as published links only; no animal records imported or custody/reunion inferred. Generic City Hall footer address not adopted as center location. Not a commercial sitter, walker, boarding or veterinary provider. No images reused, contact submitted, availability or holiday hours inferred.');
select to_jsonb(b) into changed from businesses b where id=bid;
insert into directory_private.listing_corrections(business_id,previous_values,applied_values,reason,source_reference) values(bid,'{}',changed,'Individually checked municipal animal resource; distinct from commercial pet-care expansion','https://www.ci.lathrop.ca.us/animal-services');
end $center$;
commit;
